import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Kernel: reverse cumulative sum (suffix) per element.
# For each index `idx` we compute the sum of all elements from idx to the end.
# ----------------------------------------------------------------------
elementreverse_cumsum_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reverse_cumsum_kernel(const float* a, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float sum = 0.0f;
        for (int j = idx; j < size; ++j) {
            sum += a[j];
        }
        out[idx] = sum;
    }
}
"""

# C++ function declaration.
elementreverse_cumsum_cpp_source = """
torch::Tensor reverse_cumsum_cuda(const torch::Tensor a, int dim);
"""

# Load the inline CUDA function that launches `reverse_cumsum_kernel`.
reverse_cumsum = load_inline(
    name="reverse_cumsum",
    cpp_sources=elementreverse_cumsum_cpp_source,
    cuda_sources=elementreverse_cumsum_kernel,
    functions=["reverse_cumsum_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim
        # Load the custom CUDA function for reverse cumulative sum.
        self.reverse_cumsum = reverse_cumsum  # type: ignore

    def forward(self, x):
        """
        Reverse cumulative sum along `dim`:
            out = (cumsum(x.flip(dim), dim=dim).flip(dim))
        The custom kernel computes the suffix sums on the flipped tensor.
        """
        # Flip the input along the specified dimension.
        x_flip = x.flip(self.dim)
        # Compute suffix (reverse) cumulative sum on the flipped tensor.
        out_flip = self.reverse_cumsum(x_flip, self.dim)
        # Flip back to original order.
        return out_flip.flip(self.dim)
